package eu.koboo.markup.util;

import com.mojang.authlib.properties.Property;

import java.security.SecureRandom;

public enum SkinPreset {

    PIKACHU("Pikachu", "", ""),
    GLUMANDA("Glumanda", "", ""),
    RELAXO("Relaxo", "", ""),
    LUCARIO("Lucario", "", ""),
    NACHTARA("Nachtara", "", ""),
    MACHOLLO("Machollo", "", ""),

    MARIO("Mario", "", ""),
    LUIGI("Luigi", "", ""),
    BOWSER("Bowser", "", ""),
    PEACH("Peach", "", ""),

    SONIC("Sonic", "", ""),
    SHADOW("Shadow", "", ""),
    TAILS("Tails", "", ""),

    IRONMAN("IronMan", "", ""),
    SPIDERMAN("SpiderMan", "", ""),
    VENOM("Venom", "", ""),

    SLIME("Slime", "", ""),
    BEAR("Bear", "", ""),
    CHICKEN("Chicken", "", ""),
    COW("Cow", "", ""),
    DOG("Dog", "", ""),
    ZOMBIE("Zombie", "", ""),
    CREEPER("Creeper", "", ""),
    HEROBRINE("Herobrine", "", ""),

    BATMAN("BatMan", "", ""),
    SUPERMAN("Superman", "", ""),
    FLASH("Flash", "", ""),

    LINK("Link", "", ""),

    CONSOLE("Console", "", ""),
    ;

    public static final SkinPreset[] VALUES = SkinPreset.values();
    public static final SecureRandom RANDOM = new SecureRandom();

    private final String name;
    private final Property property;

    SkinPreset(String name, String value, String sign) {
        this.name = name;
        this.property = new Property("textures", value, sign);
    }

    public String getName() {
        return name;
    }

    public Property getProperty() {
        return property;
    }
}
